// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        uint256 bn = bound(blockNumber, 15, type(uint256).max - 1);
        bn = bn - (bn % 15); // admissible: any multiple of 15
        ts = bound(ts, 1, 2 ** 200);
        vm.roll(bn);
        vm.warp(ts);
        uint256 amt = 10 ether;
        vm.deal(actor, amt);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amt}("");
        assertTrue(ok && address(c).balance == 0);
    }
}
